#!/usr/bin/env python3
"""Write the self-contained browser review from B5 manifest specifications."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1];C=R/'_checks'
IDS=['hot-air-balloon','bubble-tea','dim-sum-steamer','bento','paper-cranes','heart-locket','suitcase','postbox','camp-lantern','treasure-chest']
specs={e['vessel']['id']:e['vessel'] for e in json.loads((R/'manifest.json').read_text()) if e.get('vessel',{}).get('id')in IDS}
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>B5 art review</title>
<style>body{margin:0;background:#F6F8FB;color:#16263F;font:15px system-ui}header{position:sticky;top:0;z-index:5;background:#F6F8FBee;padding:14px;border-bottom:1px solid #C9A15A}h1{font:24px Georgia;margin:0 0 12px}.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap}input[type=range]{width:260px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;padding:12px}article{background:white;border:1px solid #DCE8F2;border-radius:12px;padding:12px}article h2{font:17px Georgia;margin:4px 0}figure{height:250px;margin:0;display:flex;align-items:center;justify-content:center}.stage,.whole,.layer,.pose{position:absolute;inset:0}.stage{position:relative;flex:none}.layer,.pose{transform-origin:0 0}.layer img,.pose img,.assembled{position:absolute;inset:0;width:100%;height:100%}p{margin:6px 0;color:#2F5D8A;font-size:12px}button,select{font:inherit}#status{font-size:12px}</style>
<header><h1>B5 food and travel · art review</h1><div class="controls"><label>Opening <input id="open" type="range" min="0" max="1" step=".01" value="0"></label><output id="progress">Closed · 0%</output><label>Size <select id="size"><option>40</option><option selected>120</option><option>230</option></select></label><label><input id="idle" type="checkbox">Idle</label><label><input id="reduced" type="checkbox">Reduce Motion</label><button id="reset">Closed</button></div><div id="status">Loading images…</div></header><main></main>
<script>const specs=__SPECS__;const root='../../../public/art/vessels/';const main=document.querySelector('main');const rows=[];let broken=0;
function img(file){const e=new Image();e.src=root+file.replace('.png','.webp');e.onerror=()=>{broken++;updateStatus()};return e}
function updateStatus(){const all=[...document.images];document.querySelector('#status').textContent=`${all.filter(i=>i.complete&&i.naturalWidth).length}/${all.length} images loaded · ${broken} errors · WebP exports`}
for(const s of Object.values(specs)){let a=document.createElement('article');a.innerHTML=`<h2>${s.id}</h2><figure><div class="stage"><div class="whole"></div></div></figure><p>${s.opening} · ${s.idleMs} ms · base ${s.baseY} · mouth ${s.mouth.x},${s.mouth.y}</p>`;main.append(a);const stage=a.querySelector('.stage'),whole=a.querySelector('.whole');const layers=[];for(const l of s.layers){const outer=document.createElement('div'),pose=document.createElement('div');outer.className='layer';pose.className='pose';pose.append(img(l.file));outer.append(pose);whole.append(outer);layers.push({l,outer,pose})}let glint;if(s.glint){glint=img(s.glint);whole.append(glint);glint.style.cssText='position:absolute;inset:0;width:100%;height:100%;opacity:0'}let sparkle;if(s.sparkle){sparkle=new Image();sparkle.src='../../../public/art/fx/fx-glint.webp';sparkle.style.position='absolute';whole.append(sparkle)}const assembled=img('vessel-'+s.id+'.png');assembled.className='assembled';stage.append(assembled);rows.push({s,stage,whole,layers,assembled,glint,sparkle})}
const controls={open:document.querySelector('#open'),size:document.querySelector('#size'),idle:document.querySelector('#idle'),reduced:document.querySelector('#reduced')};document.querySelector('#reset').onclick=()=>{controls.open.value=0;controls.idle.checked=false;controls.reduced.checked=false};
function sample(keys,t,f){const def=['scale','scaleX','scaleY','opacity'].includes(f)?1:0;let a=keys[0]||{},b=keys.at(-1)||{};for(let i=0;i<keys.length-1;i++)if(keys[i].at<=t&&keys[i+1].at>=t){a=keys[i];b=keys[i+1];break}let u=Math.max(0,Math.min(1,(t-(a.at||0))/Math.max(.001,(b.at||0)-(a.at||0))));return(a[f]??def)*(1-u)+(b[f]??def)*u}
const about=(p,size,v)=>{let x=p.x*size/1024,y=p.y*size/1024;return`translate(${x}px,${y}px) ${v} translate(${-x}px,${-y}px)`};
function idle(motions,t,size){let tr=[],opacity=1,h=.5-.5*Math.cos(2*Math.PI*t);for(const m of motions||[]){if(m.type==='float')tr.push(`translateY(${-size*m.amount*h}px)`);if(m.type==='breathe')tr.push(`scale(${1+m.amount*h})`);if(m.type==='bob')tr.push(`translateY(${size*m.amount*Math.sin(2*Math.PI*t)}px)`);if(m.type==='sway')tr.push(about(m.pivot||{x:512,y:512},size,`rotate(${m.deg*Math.sin(2*Math.PI*t)}deg)`));if(m.type==='drift'){tr.push(`translateY(${-size*m.amount*t}px)`);opacity=Math.sin(Math.PI*t)}if(m.type==='glow')opacity=m.base+m.range*(.5-.5*Math.cos(4*Math.PI*t))+(m.flicker||0)*Math.sin(10*Math.PI*t)+(m.flicker||0)*.625*Math.sin(18*Math.PI*t)}return{transform:tr.join(' '),opacity}}
function tick(ms){let size=+controls.size.value,t=+controls.open.value,on=controls.idle.checked&&!controls.reduced.checked&&t===0;document.querySelector('#progress').textContent=(t===0?'Closed':t===1?'Open':'Opening')+' · '+Math.round(t*100)+'%';for(const r of rows){const {s,stage,whole,layers,assembled}=r;stage.style.width=stage.style.height=size+'px';let phase=(ms%s.idleMs)/s.idleMs;whole.style.transformOrigin='center';Object.assign(whole.style,idle(on?s.idle:[],phase,size));assembled.style.display=controls.reduced.checked&&t===0?'block':'none';for(const {l,outer,pose}of layers){Object.assign(outer.style,idle(on?l.idle:[],phase,size));let k=l.open||[{at:0},{at:1}],p=l.pivot||{x:512,y:512};pose.style.opacity=sample(k,t,'opacity');pose.style.transform=`translate(${sample(k,t,'x')*size}px,${sample(k,t,'y')*size}px) `+about(p,size,`rotate(${sample(k,t,'rotate')}deg) scale(${sample(k,t,'scale')*sample(k,t,'scaleX')},${sample(k,t,'scale')*sample(k,t,'scaleY')})`)}if(r.sparkle){let v=on?Math.pow(Math.max(0,Math.sin(2*Math.PI*(phase-.55))),8):0;Object.assign(r.sparkle.style,{width:(size*.26)+'px',height:(size*.26)+'px',left:(s.sparkle.x*size/1024-size*.13)+'px',top:(s.sparkle.y*size/1024-size*.13)+'px',opacity:v,transform:`scale(${.5+.9*v}) rotate(${35*v}deg)`})}if(r.glint)r.glint.style.opacity=on?.9*Math.pow(Math.max(0,Math.sin(2*Math.PI*(phase-.3))),3):0}updateStatus();requestAnimationFrame(tick)}requestAnimationFrame(tick);</script>'''.replace('__SPECS__',json.dumps(specs,ensure_ascii=False))
(C/'b5-review.html').write_text(html)
lines=['# B5 food and travel art review','','All ten vessels are art only. App screens, catalogue rows and physical-phone verification are separate.','','[Contact sheet](b5-contact-sheet.png) · [40/120 px strip](b5-sizes.png) · [Interactive WebP review](b5-review.html)','','| Vessel | Opening | Review |','|---|---|---|']
for id in IDS:lines.append(f'| {id} | {specs[id]["opening"]} | [motion]({id}-motion.png) · [40/120 px]({id}-silhouette.png) |')
lines+=['','## Technical corrections','','- Bento draws box → lid → knot. The knot is gone at 0.35, then the lid lifts. Roy corrected the brief’s order.','- [Locket idle extremes](heart-locket-idle-review.png) · [Lantern glow range](camp-lantern-idle-review.png).',
'- A still stand layer lets only the locket back/chain and front sway 4° around the chain attachment; no ground layers.','- The lantern has an extra still backing so a soft, separate halo can flicker behind the glass while its flame remains present. Opening glow keys remain opacity 1 → 1.','- Bubble tea uses a thin sealed film with its straw, replacing the initial cloth-like draft.','- Glass/clear-plastic fills are marked before adjust-glass-alpha.py sets them to approximately 37.6%; outlines and highlights are preserved. Complete contents remain static.','- Isolation edits that changed position/scale were fitted to the source geometry before the common downscale; no part is upscaled.','- The approved hot-air balloon PNG/WebP bytes and motion remain fixed, including its basket rope ends.','','## Art and IP','','Original generic objects with no logo, text, real brand shape, royal cipher or character. Suitcase stickers are abstract waves, not country flags. No unresolved IP concern found in the visual review. Natural food colours are limited to food, per Roy’s approved STYLE.md exception.','','## Review status','','Local checks: ten exact raw CLOSED stacks, 36 alpha-exact WebPs, 261/261 PNG masters, 452 existing/approved artwork hashes and root build pass. The browser tool rejected the file URL; the page has only been syntax-checked and static sheets were visually inspected.',
'Roy approved PR #70 on 2026-11-08; merge follows fresh checks and green CI. These review controls reproduce the manifest transforms in a standalone page; they do not constitute screen integration or a physical-device test.','']
(C/'b5-review.md').write_text('\n'.join(lines));print('B5 browser review and notes generated')
